// Renders the suite hub sections from window.SUITE (suite-data.js) and window.SUITE_INDEX (suite-index.js,
// generated by tools/suite-index.py). Targets are elements with data-suite="..."; hrefs are prefixed with
// <body data-base="..."> ("" at the root, "../" one folder down). Reading state comes from window.SuiteStore
// (suite-nav.js); without it everything still renders, just without checkmarks.

(function () {
  var S = window.SUITE;
  if (!S) return;
  var IX = window.SUITE_INDEX || { lessons: {}, decks: [], diagrams: [] };
  var BASE = document.body.getAttribute("data-base") || "";
  var NOOP = { isDone: function () { return false; }, setDone: function () {}, last: function () { return null; },
               ui: function () { return {}; }, setUi: function () {}, sim: function () { return {}; } };
  function store() { return window.SuiteStore || NOOP; }

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (k) {
      if (attrs[k] == null) return;
      if (k === "class") node.className = attrs[k];
      else if (k === "text") node.textContent = attrs[k];
      else node.setAttribute(k, attrs[k]);
    });
    (children || []).forEach(function (c) {
      if (c) node.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    });
    return node;
  }

  function parseDate(iso) { var p = iso.split("-").map(Number); return new Date(p[0], p[1] - 1, p[2]); }
  function shortDate(iso) {
    try { return parseDate(iso).toLocaleDateString("es-AR", { day: "numeric", month: "short" }); } catch (e) { return iso; }
  }
  function startOfToday() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
  function daysUntil(iso) { return Math.round((parseDate(iso) - startOfToday()) / 86400000); }

  var STATUS = {
    "listo": ["Lección lista", "ok"],
    "pendiente-leccion": ["PDF listo · lección en camino", "warn"],
    "pendiente-pdf": ["Falta el PDF", "warn"],
    "fuera-tp": ["Fuera del TP", "todo"],
  };
  var SECTION_STATUS = {
    "guia": ["Guía disponible", "ok"],
    "pendiente-guia": ["Guía en camino", "warn"],
    "pendiente-clase": ["Espera una clase", "warn"],
    "al-final": ["Se arma al final", "todo"],
  };
  var MILESTONE = { entrega: "Entrega TP", parcial: "Parcial", defensa: "Defensa TP", recuperatorio: "Recuperatorio" };
  var ROUTES = {
    agil: { title: "Ruta 2 · Metodologías ágiles", sub: function () { return "Clases 8 a 13 · parcial del " + shortDate(S.dates.parcial); } },
    cascada: { title: "Ruta 1 · Cascada", sub: function () { return "Clases 1 a 7 · TP entregado · defensa del " + shortDate(S.dates.defensa); } },
  };

  function chip(pair) { return el("span", { class: "chip " + pair[1], text: pair[0] }); }

  function lessonPaths(c) {
    if (!c.lesson || (c.status !== "listo" && !c.placeholder)) return [];
    return [c.lesson].concat(c.lessonMore || []);
  }
  function partLabel(c, path, i) {
    if (i === 0) return (c.lessonMore || []).length ? "Parte 1 · lección principal" : "Lección";
    return (c.lessonMoreLabels && c.lessonMoreLabels[i - 1]) || path.split("/").pop().replace(".html", "");
  }
  function diagramsOf(paths) {
    var seen = [];
    paths.forEach(function (p) { ((IX.lessons[p] || {}).diagrams || []).forEach(function (d) { if (seen.indexOf(d) < 0) seen.push(d); }); });
    return seen.map(function (slug) {
      return IX.diagrams.filter(function (d) { return d.slug === slug; })[0] || { slug: slug, title: slug };
    });
  }
  function hasSection(path, id) {
    return ((IX.lessons[path] || {}).sections || []).some(function (s) { return s[0] === id; });
  }

  // ── Collapsible state ────────────────────────────────────────────────
  function remembered(det, id, fallback) {
    var ui = store().ui();
    det.open = id in ui ? !!ui[id] : fallback;
    det.addEventListener("toggle", function () { store().setUi(id, det.open); });
    return det;
  }

  // ── Routes ───────────────────────────────────────────────────────────
  function doneDot(paths) {
    var n = paths.filter(function (p) { return store().isDone(p); }).length;
    var cls = !paths.length || !n ? "" : n === paths.length ? " full" : " half";
    return el("span", { class: "done-dot" + cls, title: paths.length ? n + " de " + paths.length + " partes leídas" : "" });
  }

  function lessonRow(c, onChange) {
    var paths = lessonPaths(c);
    var ready = paths.length > 0 && !c.placeholder;
    var decks = c.slides ? [c.slides] : [];
    var figs = diagramsOf(paths);

    var dot = doneDot(paths);
    var title = ready ? el("a", { href: BASE + c.lesson, text: c.title }) : document.createTextNode(c.title);
    var badges = el("span", { class: "badges" });
    if (paths.length > 1) badges.appendChild(chip([paths.length + " partes", "todo"]));
    if (decks.length) badges.appendChild(chip(["Slides", "todo"]));
    if (figs.length) badges.appendChild(chip([figs.length + (figs.length === 1 ? " diagrama" : " diagramas"), "todo"]));
    if (c.milestone) badges.appendChild(chip([MILESTONE[c.milestone], "warn"]));
    if (!ready) badges.appendChild(chip([c.placeholder ? "Reservada" : (STATUS[c.status] || ["Sin lección"])[0], "todo"]));

    var summary = el("summary", {}, [
      dot,
      el("span", { class: "num" }, ["C" + c.number, el("small", { text: shortDate(c.date) })]),
      el("span", { class: "ttl" }, [title]),
      badges,
    ]);

    var body = el("div", { class: "lesson-body" }, [el("p", { text: c.topics })]);
    if (!paths.length) {
      body.appendChild(el("p", { text: c.track === "agil" ? "Sin material de la cátedra todavía; entra en el parcial." : (c.unlocks || "") }));
    } else {
      body.appendChild(el("h4", { text: paths.length > 1 ? "Partes · tildar al terminar" : "Tildar al terminar" }));
      var list = el("ul", { class: "parts" });
      paths.forEach(function (p, i) {
        var box = el("input", { type: "checkbox" });
        box.checked = store().isDone(p);
        box.addEventListener("change", function () {
          store().setDone(p, box.checked);
          var fresh = doneDot(paths);
          dot.replaceWith(fresh);
          dot = fresh;
          onChange();
        });
        list.appendChild(el("li", {}, [el("label", {}, [box, el("a", { href: BASE + p, text: partLabel(c, p, i) })])]));
      });
      body.appendChild(list);

      paths.forEach(function (p, i) {
        var secs = (IX.lessons[p] || {}).sections || [];
        if (!secs.length) return;
        body.appendChild(el("h4", { text: paths.length > 1 ? "Secciones · " + partLabel(c, p, i) : "Secciones" }));
        var ol = el("ul", { class: "ideas" });
        secs.forEach(function (s) {
          var key = /^(trampas|practica)/.test(s[0]);
          ol.appendChild(el("li", { class: key ? "is-key" : null }, [el("a", { href: BASE + p + "#" + s[0], text: s[1] })]));
        });
        body.appendChild(ol);
      });

      if (figs.length) {
        body.appendChild(el("h4", { text: "Diagramas" }));
        body.appendChild(el("div", { class: "mini-figs" }, figs.map(function (d) {
          return el("a", { href: BASE + "diagramas/" + d.slug + ".html", text: d.title });
        })));
      }
      var row = el("div", { class: "links-row" }, [el("a", { class: "btn primary", href: BASE + c.lesson, text: "Abrir lección" })]);
      decks.forEach(function (d) { row.appendChild(el("a", { class: "btn", href: BASE + d, text: "Slides" })); });
      paths.forEach(function (p) { if (hasSection(p, "trampas")) row.appendChild(el("a", { class: "btn", href: BASE + p + "#trampas", text: "Trampas" + (paths.length > 1 ? " · " + p.split("/").pop().split("-")[0] : "") })); });
      body.appendChild(row);
    }

    var det = el("details", { class: "lesson" + (paths.length ? "" : " is-off") }, [summary, body]);
    return remembered(det, "lesson-" + c.number, false);
  }

  function renderRoutes(target) {
    var tracks = (target.getAttribute("data-tracks") || "agil,cascada").split(",");
    tracks.forEach(function (track) {
      var R = ROUTES[track];
      if (!R) return;
      var classes = S.classes.filter(function (c) { return c.track === track; });
      var all = [];
      classes.forEach(function (c) { if (!c.placeholder) all = all.concat(lessonPaths(c)); });
      var count = el("span", { class: "count" });
      function paintCount() {
        var n = all.filter(function (p) { return store().isDone(p); }).length;
        count.textContent = "";
        count.appendChild(document.createTextNode(n + " de " + all.length + " leídas"));
        count.appendChild(el("div", { class: "bar" }, [el("span", { style: "width:" + (all.length ? Math.round(100 * n / all.length) : 0) + "%" })]));
      }
      paintCount();
      var summary = el("summary", {}, [
        el("span", { class: "chev", text: "▸" }),
        el("h2", { text: R.title }),
        count,
        el("span", { class: "sub", text: R.sub() }),
      ]);
      var body = el("div", { class: "route-body" });
      classes.forEach(function (c) { body.appendChild(lessonRow(c, paintCount)); });
      var extras = (S.extras || []).filter(function (x) { return x.track === track && x.status === "listo"; });
      if (extras.length) {
        body.appendChild(el("h3", { text: track === "agil" ? "Repasar e integrar" : "Integrar y defender" }));
        body.appendChild(el("div", { class: "extras-list" }, extras.map(function (x) {
          return el("a", { href: BASE + x.path }, [el("strong", { text: x.title }), el("span", { text: x.description })]);
        })));
      }
      var det = el("details", { class: "route is-" + track }, [summary, body]);
      target.appendChild(remembered(det, "route-" + track, track === "agil"));
    });
  }

  // Buttons: <button data-fold="open|close" data-scope="#id">
  function wireFoldButtons() {
    Array.prototype.forEach.call(document.querySelectorAll("[data-fold]"), function (b) {
      b.addEventListener("click", function () {
        var scope = document.querySelector(b.getAttribute("data-scope")) || document;
        var open = b.getAttribute("data-fold") === "open";
        Array.prototype.forEach.call(scope.querySelectorAll("details.route, details.lesson"), function (d) {
          if (d.open !== open) d.open = open;
        });
      });
    });
  }

  // ── Dates ────────────────────────────────────────────────────────────
  function renderWhen(target) {
    var items = S.classes.filter(function (c) { return c.milestone && daysUntil(c.date) >= 0; });
    items.forEach(function (c, i) {
      var d = daysUntil(c.date);
      target.appendChild(el("div", { class: i === 0 ? "main" : null }, [
        el("div", { class: "n", text: d === 0 ? "Hoy" : d === 1 ? "Mañana" : d + " días" }),
        el("div", { class: "l", text: MILESTONE[c.milestone] + " · " + shortDate(c.date) }),
      ]));
    });
    if (!items.length) target.appendChild(el("div", {}, [el("div", { class: "n", text: "✓" }), el("div", { class: "l", text: "Sin evaluaciones pendientes" })]));
  }

  // ── Resume + simulacro score (fills static tiles) ────────────────────
  function renderResume(target) {
    var last = store().last();
    if (!last || !last.path) { target.hidden = true; return; }
    target.href = BASE + last.path + (last.id ? "#" + last.id : "");
    target.querySelector("strong").textContent = last.title;
    target.querySelector("span").textContent = last.section ? "Última sección: " + last.section : "Volver a la última lección abierta";
  }
  function renderSimScore(target) {
    var h = (store().sim().history || []);
    if (!h.length) return;
    var x = h[h.length - 1];
    target.textContent = "Último intento: " + x.right + "/" + x.total + " (" + x.pct + " %) · " + x.date;
  }

  function renderSimHistory(target) {
    var sim = store().sim();
    var h = sim.history || [];
    if (!h.length) {
      target.appendChild(el("p", { text: "Todavía no hay intentos guardados en este navegador. Los resultados quedan en el navegador donde se rinde: otra PC empieza vacía." }));
      return;
    }
    var bars = el("div", { class: "history", role: "img", "aria-label": "Porcentaje de los últimos intentos: " + h.map(function (x) { return x.pct + " %"; }).join(", ") });
    var dates = el("div", { class: "history-dates", "aria-hidden": "true" });
    h.forEach(function (x, i) {
      bars.appendChild(el("div", { class: "col" + (i === h.length - 1 ? " is-last" : "") }, [
        el("b", { text: x.pct + "%" }), el("i", { style: "height:" + Math.max(2, x.pct) + "%" }),
      ]));
      dates.appendChild(el("span", { text: x.date.slice(0, 5) }));
    });
    target.appendChild(bars);
    target.appendChild(dates);
    var failed = sim.lastFailed || [];
    target.appendChild(el("p", { class: "quiz-score", text: failed.length
      ? "En el último intento se fallaron " + failed.length + ": " + failed.join(", ") + ". En el simulacro, «Reintentar solo las falladas» las vuelve a tomar."
      : "En el último intento no se falló ninguna." }));
  }

  // ── Practice lists per route ─────────────────────────────────────────
  function renderTraps(target) {
    var track = target.getAttribute("data-track") || "agil";
    var ul = el("ul", { class: "trap-list" });
    S.classes.filter(function (c) { return c.track === track; }).forEach(function (c) {
      lessonPaths(c).forEach(function (p) {
        var secs = (IX.lessons[p] || {}).sections || [];
        var pick = secs.filter(function (s) { return /^(trampas|practica)/.test(s[0]); });
        if (!pick.length) return;
        var name = "C" + (lessonPaths(c).length > 1 ? p.split("/").pop().split("-")[0] : c.number);
        ul.appendChild(el("li", {}, [el("strong", { text: name + " " })].concat(pick.map(function (s, i) {
          return el("span", {}, [i ? " · " : "", el("a", { href: BASE + p + "#" + s[0], text: s[0] === "trampas" ? "trampas" : s[1].replace(/^Práctica \d+ · /, "").toLowerCase() })]);
        }))));
      });
    });
    target.appendChild(ul);
  }

  // ── Decks ────────────────────────────────────────────────────────────
  function deckClasses(path) {
    return S.classes.filter(function (c) { return c.slides === path; });
  }
  function renderDecks(target) {
    var group = target.getAttribute("data-group") || "agil";
    var decks = IX.decks.filter(function (d) {
      var cs = deckClasses(d.path);
      return group === "agil" ? cs.length > 0 : cs.length === 0;
    });
    decks.forEach(function (d) {
      var cs = deckClasses(d.path);
      var frame = el("iframe", { src: BASE + d.path, loading: "lazy", tabindex: "-1", "aria-hidden": "true", title: "" });
      var thumb = el("a", { class: "thumb", href: BASE + d.path, "aria-label": "Abrir " + d.title }, [frame]);
      var row = el("div", { class: "links-row" }, [el("a", { class: "btn primary", href: BASE + d.path, text: "Presentar" })]);
      cs.forEach(function (c) { if (c.lesson) row.appendChild(el("a", { class: "btn", href: BASE + c.lesson, text: "Lección C" + c.number })); });
      target.appendChild(el("article", { class: "deck" }, [
        thumb,
        el("div", { class: "meta-row" }, [
          el("strong", { text: d.title }),
          el("span", { text: (/-web\//.test(d.path) ? "Versión web · " : "") + d.slides + " slides" + (cs.length ? " · clase" + (cs.length > 1 ? "s " : " ") + cs.map(function (c) { return c.number; }).join(" y ") : "") }),
          row,
        ]),
      ]));
    });
    function fit() {
      Array.prototype.forEach.call(target.querySelectorAll(".thumb"), function (t) {
        t.firstChild.style.transform = "scale(" + t.clientWidth / 1280 + ")";
      });
    }
    fit();
    window.addEventListener("resize", fit);
  }

  // ── Legacy renderers (clases/_template.html and older pages) ─────────
  function renderCountdown(target) {
    [["entrega", "Entrega del TP"], ["parcial", "Parcial ágil"], ["defensa", "Defensa del TP"]].forEach(function (item) {
      var iso = S.dates[item[0]];
      var d = daysUntil(iso);
      var n = d > 0 ? String(d) : d === 0 ? "Hoy" : "Pasó";
      var label = d > 0 ? "días · " + item[1] + " · " + shortDate(iso) : item[1] + " · " + shortDate(iso);
      target.appendChild(el("div", {}, [el("div", { class: "n", text: n }), el("div", { class: "l", text: label })]));
    });
  }

  function renderTimeline(target) {
    var today = startOfToday();
    var current = null;
    S.classes.forEach(function (c) { if (parseDate(c.date) <= today) current = c.number; });
    S.classes.forEach(function (c) {
      var cls = c.track === "agil" ? "is-agile" : c.track === "eval" ? "is-eval" : "";
      if (c.number === current) cls += " is-today";
      target.appendChild(el("li", { class: cls.trim(), title: c.title }, [
        el("b", { text: "C" + c.number }),
        shortDate(c.date),
        c.milestone ? el("div", { text: MILESTONE[c.milestone] }) : null,
      ]));
    });
  }

  function classCard(c) {
    var ready = c.status === "listo" && c.lesson;
    var pair = STATUS[c.status] || ["", "todo"];
    var linked = ready || (c.placeholder && c.lesson);
    var title = linked ? el("a", { href: BASE + c.lesson, text: c.title }) : document.createTextNode(c.title);
    var children = [
      el("div", { class: "top" }, [el("span", { text: "Clase " + c.number + " · " + shortDate(c.date) }), chip(pair)]),
      el("h3", {}, [title]),
      el("p", { text: c.topics }),
    ];
    if (ready) {
      (c.lessonMore || []).forEach(function (path, i) {
        var label = (c.lessonMoreLabels && c.lessonMoreLabels[i]) || path.split("/").pop().replace(".html", "");
        children.push(el("p", {}, [el("a", { href: BASE + path, text: "Continúa: " + label })]));
      });
    }
    if (ready && c.slides) children.push(el("p", {}, [el("a", { href: BASE + c.slides, text: "Slides de la clase" })]));
    if (c.milestone) children.push(el("p", {}, [chip(["" + MILESTONE[c.milestone], "warn"])]));
    var cls = "card" + (ready ? "" : " is-disabled") + (c.track === "agil" ? " is-agile" : "");
    return el("div", { class: cls }, children);
  }
  function renderClasses(target) {
    var tracks = (target.getAttribute("data-tracks") || "cascada,agil,eval").split(",");
    S.classes.filter(function (c) { return tracks.indexOf(c.track) !== -1; })
      .forEach(function (c) { target.appendChild(classCard(c)); });
  }
  function renderExtras(target) {
    var tracks = (target.getAttribute("data-tracks") || "cascada,agil").split(",");
    S.extras.filter(function (x) { return tracks.indexOf(x.track) !== -1; }).forEach(function (x) {
      var ready = x.status === "listo";
      var title = ready ? el("a", { href: BASE + x.path, text: x.title }) : document.createTextNode(x.title);
      var label = x.track === "agil" ? "Repaso · bloque ágil" : "Integración · bloque cascada";
      target.appendChild(el("div", { class: "card" + (ready ? "" : " is-disabled") + (x.track === "agil" ? " is-agile" : "") }, [
        el("div", { class: "top" }, [el("span", { text: label }), chip(STATUS[x.status] || ["", "todo"])]),
        el("h3", {}, [title]),
        el("p", { text: x.description }),
      ]));
    });
  }
  function renderTpChain(target) {
    S.tpSections.forEach(function (s) {
      var feeds = s.feedsFrom.map(function (n) { return "clase " + n; }).join(" + ");
      var link = s.page ? el("a", { href: BASE + s.page, text: s.number + ". " + s.title }) : null;
      target.appendChild(el("li", feeds ? { "data-in": feeds } : {}, [
        link || el("strong", { text: s.number + ". " + s.title }), " ",
        chip(SECTION_STATUS[s.status] || ["", "todo"]),
        el("span", { class: "q", text: s.question }),
      ]));
    });
  }

  var RENDERERS = {
    when: renderWhen,
    routes: renderRoutes,
    resume: renderResume,
    "sim-score": renderSimScore,
    "sim-history": renderSimHistory,
    traps: renderTraps,
    decks: renderDecks,
    countdown: renderCountdown,
    timeline: renderTimeline,
    classes: renderClasses,
    extras: renderExtras,
    "tp-chain": renderTpChain,
  };

  function run() {
    Array.prototype.forEach.call(document.querySelectorAll("[data-suite]"), function (target) {
      var fn = RENDERERS[target.getAttribute("data-suite")];
      if (fn) fn(target);
    });
    wireFoldButtons();
  }
  // suite-nav.js is deferred; wait for it so reading state is available.
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run);
  else run();
})();
